import {canSubmitAnswer} from './answerValidity.js';
import {personalTagline, questionHint} from './copy.js';
import {selectControl} from './controls.js';
export const threadNav = [
  ['discover','Discover','home-smile-linear'],['search','Search','magnifer-linear'],
  ['wallet','Wallet','wallet-money-linear'],['saved','Saved polls','heart-linear'],
  ['polls','My polls','users-group-rounded-linear'],['overview','Insights','chart-square-linear'],
];
const avatarFor=p=>p.avatar|| (p.name==='Quiet Orbit'?'orbit':p.name==='River Stone'?'river':p.name==='Soft Signal'?'willow':'otter');
export function threadShell(content, c) {
  const { state, icon, logo, ib } = c;
  const settingsPage = state.view === "settings";
  const count = state.preferences?.notifications === false ? 0 : (state.notifications || []).filter((n) => !n.read).length;
  const notificationButton = `<button class="thread-nav-item notification-launcher" data-action="notifications" aria-label="Notifications${count ? ", " + count + " unread" : ""}">${icon("bell-linear")}<span class="notification-badge" data-notification-badge ${count ? "" : "hidden"}>${count > 99 ? "99+" : count}</span><span class="nav-tooltip">Notifications</span></button>`;
  const nav = (view, label, ic) => `<a class="thread-nav-item" href="#${view}" data-nav="${view}" aria-label="${label}" ${state.view === view ? 'aria-current="page"' : ""}>${icon(view === "discover" && state.view !== "discover" ? "home-outline" : ic)}<span class="nav-tooltip">${label}</span></a>`;
  return `<div class="threads-app ${state.view === "discover" && state.mobileAnswer ? "focused-thread" : ""}"><nav class="thread-rail" aria-label="Main navigation"><a href="#discover" data-nav="discover" class="thread-brand" aria-label="Poll Pilled home">${logo()}</a><div class="thread-rail-links">${threadNav.map((n) => nav(...n)).join("")}${notificationButton}</div><div class="rail-topics" aria-label="Topics">${[["Design", "gallery-linear"], ["Work", "card-linear"], ["Lifestyle", "sun-2-linear"]].map(([t, i]) => `<button class="thread-nav-item" data-action="sidebar-topic" data-topic="${t}" aria-label="${t} polls">${icon(i)}<span class="nav-tooltip">${t}</span></button>`).join("")}</div><div class="thread-rail-bottom"><button class="thread-nav-item" data-action="thread-menu" aria-label="More">${icon("hamburger-menu-linear")}<span class="nav-tooltip">More</span></button><a class="thread-create" href="#create" data-nav="create" aria-label="Create a poll">${icon("add-linear")}</a></div></nav><header class="thread-mobile-header">${ib(state.mobileAnswer || settingsPage ? "arrow-left-linear" : "hamburger-menu-linear", state.mobileAnswer ? "Back to polls" : settingsPage ? state.settings === "menu" ? "Back to Discover" : "Back to settings" : "More", state.mobileAnswer ? "back-polls" : settingsPage ? state.settings === "menu" ? "discover" : "settings-home" : "thread-menu")}<a href="#discover" data-nav="discover" class="thread-brand" aria-label="Poll Pilled home">${logo()}</a>${notificationButton}</header>${content}<nav class="thread-mobile-nav" aria-label="Main navigation">${nav("discover", "Discover", "home-smile-linear")}${nav("wallet", "Wallet", "wallet-money-linear")}<a class="thread-nav-item create-slot" href="#create" data-nav="create" aria-label="Create a poll">${icon("add-linear")}</a>${nav("saved", "Saved polls", "heart-linear")}${nav("settings", "Settings", "users-group-rounded-linear")}</nav></div>`;
}
export function threadColumnHead(title,action='',c,back=''){const tag=title==='Your workspace'?'h2':'h1';return `<header class="thread-column-head"><div class="page-heading">${back}<${tag}>${title}</${tag}></div>${action}</header>`;}
export function threadPoll(p,c,focused=false,priority=focused){const {state,icon,ib,answerControls,results,esc,formats}=c,done=state.completed[p.id]||p.mine;
 return `<article class="thread-poll ${focused?'is-focused':''}" data-poll-id="${p.id}" id="poll-${p.id}"><img class="thread-avatar" src="/assets/avatar-${avatarFor(p)}.png" alt="" width="36" height="36" decoding="async" loading="${priority?'eager':'lazy'}"><div class="thread-post"><header class="thread-author">${p.can_follow||p.mine?`<button class="author-identity publisher-identity" data-action="publisher-profile" data-id="${esc(p.creator_id)}"><span class="author-name">${esc(p.name)}</span>${personalTagline(p.tagline)?`<span class="author-tagline">${esc(personalTagline(p.tagline))}</span>`:''}</button>`:`<div class="author-identity"><span class="author-name">${esc(p.name)}</span>${personalTagline(p.tagline)?`<span class="author-tagline">${esc(personalTagline(p.tagline))}</span>`:''}</div>`}${p.can_follow?`<button class="publisher-follow" data-action="follow-publisher" data-id="${esc(p.creator_id)}" data-following="${!!p.followed_creator}" aria-pressed="${!!p.followed_creator}" aria-label="${p.followed_creator?'Unfollow':'Follow'} ${esc(p.name)}">${p.followed_creator?'Following':'+ Follow'}</button>`:''}${ib('menu-dots-linear','Poll options','poll-options')}</header><h2 class="thread-question" tabindex="-1">${esc(p.title)}</h2><div class="thread-poll-meta"><span>${p.seconds} sec</span>${p.ai?`<span class="poll-origin">${[p.text_origin==='generated'?'AI question':'',p.image_origin==='generated'?'AI visuals':'',p.audio_origin==='generated'?'AI voice':'',p.video_origin==='generated'?'AI video':''].filter(Boolean).join(' · ')||'AI-created'}</span>`:''}<span class="reward-inline">+${p.reward} pts</span></div>${done?results(p):`<div class="poll-answers">${answerControls(p,false,priority)}</div>`}<footer class="thread-poll-footer">${done?`<span class="receipt-note">${icon('check-circle-linear','sm')}Answered</span><button class="icon-btn" data-action="save-poll" aria-label="${state.saved.has(p.id)?'Unsave poll':'Save poll'}" aria-pressed="${state.saved.has(p.id)}">${icon('bookmark-linear')}</button>`:`<span class="locked-note">${icon('lock-keyhole-linear','sm')}${p.eligible?'Results after voting':esc(p.eligibility_reason)}</span><button class="btn primary" data-action="submit" ${!p.eligible||!canSubmitAnswer(p,state.answers[p.id])?'disabled':''}>Submit</button>`}</footer></div></article>`;
}
export function threadDiscover(c){const {state,ib,icon,button,matches,activePoll,empty}=c;
 if(state.mobileAnswer)return `<main class="thread-single focus-page" id="main">${threadColumnHead('Poll','',c,ib('arrow-left-linear','Back to polls','back-polls'))}<div class="thread-panel thread-focus">${threadPoll(activePoll(),c,true)}</div></main>`;
 const list=matches();return `<main class="thread-columns ${state.sideColumn?'':'one-column'}" id="main"><section class="thread-column">${threadColumnHead(state.feedTab==='following'?'Following':state.topic==='For you'?'For you':state.topic,ib('tuning-2-linear','Feed preferences','feed-preferences'),c)}<div class="thread-panel thread-feed" id="thread-feed"><div class="thread-mobile-tabs" role="group" aria-label="Poll feed"><button data-action="feed-tab" data-tab="foryou" aria-pressed="${state.feedTab!=='following'}">For you</button><button data-action="feed-tab" data-tab="following" aria-pressed="${state.feedTab==='following'}">Following</button></div><div class="thread-composer"><img src="/assets/avatar-${state.avatar||'otter'}.png" alt="" width="36" height="36"><button class="composer-prompt" data-action="new-poll">Ask a question</button>${button('Create','new-poll')}</div>${state.topic!=='For you'||state.query?`<div class="filter-summary"><span>${state.query?'Search: '+c.esc(state.query):state.topic}</span><button class="link" data-action="clear-filters">Clear</button></div>`:''}${list.length?list.map((p,i)=>threadPoll(p,c,false,i===0)).join(''):(state.feedTab==='following'?empty('Your next favourites start here',state.following?.length?'No matching open polls right now. Check back or explore other polls.':'Follow a publisher from a poll to see their questions here.','Explore polls','find-publishers','following'):empty('Nothing here just yet','Try another topic or change your interests.','Adjust interests','interests','discover'))}${list.length?'<div class="feed-end">You’re all caught up. <button class="link" data-action="interests">Tune your interests</button></div>':''}</div></section>${state.sideColumn?`<aside class="thread-column workspace-column">${threadColumnHead('Your workspace',ib('menu-dots-linear','Workspace column options','column-menu'),c)}<div class="thread-panel">${workspace(c)}</div></aside>`:''}</main>`;
}
function workspace(c){const {state,icon,button,esc,empty}=c;return `<section class="thread-workspace-profile"><div class="workspace-identity"><div><h2>${esc(state.name)}</h2>${personalTagline(state.tagline)?`<p>${esc(personalTagline(state.tagline))}</p>`:''}</div><img src="/assets/avatar-${state.avatar||'otter'}.png" alt="Your anonymous otter avatar" width="84" height="84"></div><div class="workspace-balance"><button class="link" data-nav="wallet">${state.points.toLocaleString()} points</button><span>${state.pending} pending</span></div>${button('View wallet','wallet-page','','style="width:100%"')}<div class="publisher-reach"><span>${state.followersCount||0} ${(state.followersCount||0)===1?'follower':'followers'}</span><button class="link" data-action="manage-following">Following ${state.following?.length||0}</button></div></section><div class="workspace-tabs" role="tablist" aria-label="Your polls"><button role="tab" id="workspace-tab-live" aria-controls="workspace-polls-panel" tabindex="${state.rightTab==='live'?0:-1}" data-action="workspace-tab" data-tab="live" aria-selected="${state.rightTab==='live'}">Live</button><button role="tab" id="workspace-tab-drafts" aria-controls="workspace-polls-panel" tabindex="${state.rightTab==='drafts'?0:-1}" data-action="workspace-tab" data-tab="drafts" aria-selected="${state.rightTab==='drafts'}">Drafts</button><button role="tab" id="workspace-tab-saved" aria-controls="workspace-polls-panel" tabindex="${state.rightTab==='saved'?0:-1}" data-action="workspace-tab" data-tab="saved" aria-selected="${state.rightTab==='saved'}">Saved</button></div><div class="workspace-list" role="tabpanel" id="workspace-polls-panel" aria-labelledby="workspace-tab-${state.rightTab}">${state.rightTab==='live'?`${state.published.map(p=>`<div class="workspace-poll-row"><span class="workspace-poll-icon">${icon(c.formats[p.type][1])}</span><div><strong>${esc(p.title)}</strong><p>${p.responses} of ${p.cap} responses</p></div>${button('Results','publisher-results','small',`data-id="${p.id}"`)}</div>`).join('')||empty('No polls yet','','Create a poll','new-poll','drafts',true)}`:state.rightTab==='drafts'?(state.drafts.length?state.drafts.map(d=>`<div class="workspace-poll-row"><span class="workspace-poll-icon">${icon('checklist-minimalistic-linear')}</span><div><strong>${esc(d.title)}</strong><p>Draft · ${d.topic}</p></div>${button('Edit','edit-draft','small',`data-id="${d.id}"`)}</div>`).join(''):empty('No drafts yet','','Create a poll','new-poll','drafts',true)):(state.saved.size?`<p class="workspace-quiet">${state.saved.size} saved ${state.saved.size===1?'poll':'polls'} ${button('View saved','saved-page','small')}</p>`:empty('No saved polls','Answer a poll, then save its results.','Find polls','discover','saved',true))}</div>${c.connected.workspaceExtras()}`;}
export function threadSearch(c){const {state,icon,matches,empty,queueItem}=c;const list=matches();return `<main class="thread-single search-page" id="main"><header class="thread-search-head"><h1 class="sr-only" tabindex="-1">Search</h1><label class="search">${icon('magnifer-linear')}<input id="poll-search" type="search" aria-label="Search polls" placeholder="Search" value="${c.esc(state.query)}" autocomplete="off"></label>${c.ib('tuning-2-linear','Search filters','feed-preferences')}</header><div class="thread-panel"><h2 class="search-caption">${state.query?list.length+' matching '+(list.length===1?'poll':'polls'):'Explore polls'}</h2><div id="search-results">${list.length?list.map(queueItem).join(''):empty('No matching polls','Try a different word or topic.','Clear search','clear-filters','discover')}</div></div></main>`;}
export function threadSettings(c) {
  const { state, icon, ib, settingsBody } = c;
  if (state.settings !== "menu") return `<main class="thread-single settings-single" id="main">${threadColumnHead({ appearance: "Appearance", interests: "Interests", profile: "Your identity", privacy: "Privacy" }[state.settings] || "Settings", "", c, ib("arrow-left-linear", "Back to settings", "settings-home"))}<section class="thread-panel settings-panel settings-flow">${settingsBody()}</section></main>`;
  return `<main class="thread-single settings-single settings-root" id="main">${threadColumnHead("Settings", "", c)}<section class="thread-panel settings-directory">${[["profile", "users-group-rounded-linear", "Your identity", "Your anonymous name and tagline"], ["interests", "tuning-2-linear", "Interests", "Topics, formats, and AI preferences"], ["appearance", "sun-2-linear", "Appearance", ""], ["privacy", "lock-keyhole-linear", "Privacy", ""]].map(([id, ic, label, desc]) => `<button class="settings-directory-row" data-action="settings-section" data-section="${id}">${icon(ic)}<span><strong>${label}</strong>${desc ? `<small>${desc}</small>` : ""}</span>${icon("alt-arrow-right-linear", "sm")}</button>`).join("")}<a class="settings-directory-row" href="/welcome">${icon("stars-linear")}<span><strong>Personalize your experience</strong><small>Revisit your setup preferences</small></span>${icon("alt-arrow-right-linear", "sm")}</a><a class="settings-directory-row" href="/sign-in?mode=reset">${icon("lock-keyhole-linear")}<span><strong>Password & sign-in</strong><small>Set or reset your password</small></span>${icon("alt-arrow-right-linear", "sm")}</a><button class="settings-directory-row" data-action="manage-following">${icon("users-group-rounded-linear")}<span><strong>Following</strong><small>Publishers and new-poll alerts</small></span>${icon("alt-arrow-right-linear", "sm")}</button><button class="settings-directory-row" data-action="notifications">${icon("bell-linear")}<span><strong>Notifications</strong></span>${icon("alt-arrow-right-linear", "sm")}</button><button class="settings-directory-row" data-action="invite-friends">${icon("users-group-rounded-linear")}<span><strong>Invite friends</strong></span>${icon("alt-arrow-right-linear", "sm")}</button><button class="settings-directory-row" data-nav="wallet">${icon("wallet-money-linear")}<span><strong>Wallet</strong><small>Earnings and publishing credits</small></span>${icon("alt-arrow-right-linear", "sm")}</button><button class="settings-directory-row" data-action="prototype-info">${icon("question-circle-linear")}<span><strong>About Poll Pilled</strong></span>${icon("alt-arrow-right-linear", "sm")}</button>${state.admin ? '<button class="settings-directory-row" data-action="open-admin"><span><strong>Platform administration</strong><small>Only visible to your admin account</small></span></button>' : ""}${state.authenticated ? '<button class="settings-directory-row" data-action="sign-out"><span><strong>Sign out</strong></span></button>' : ""}<p class="prototype-footnote">Poll Pilled</p></section></main>`;
}
export function threadEditor(c) {
  const { state, icon, ib, button, esc, formats, budgetSummary } = c, e = state.editor;
  return `<main class="thread-single creation-page" id="main">${threadColumnHead("New poll", button("Save draft", "save-draft"), c, ib("arrow-left-linear", "Close editor", "close-editor"))}<form class="thread-panel creation-panel" id="editor-form"><div class="compose-body"><img class="thread-avatar" src="/assets/avatar-${state.avatar || "otter"}.png" alt="" width="36" height="36"><div class="compose-content"><strong class="author-name">${esc(state.name || "Your poll")}</strong><label class="field-label" for="editor-title">Question</label><textarea id="editor-title" class="compose-question" maxlength="180" aria-describedby="question-count" placeholder="${questionHint(e.type)}">${esc(e.title)}</textarea><span id="question-count" class="sr-only">${e.title.length}/180</span>${c.connected.starter()}<div class="compose-toolbar" role="group" aria-label="Poll format">${Object.entries(formats).map(([key, [label, ic]]) => `<button type="button" class="icon-btn format-tool" data-action="editor-format" data-format="${key}" aria-label="${label}" aria-pressed="${e.type === key}">${icon(ic)}<span class="tool-label">${label}</span></button>`).join("")}</div><div class="row ai-editor-actions">${button(icon("stars-linear") + "<span>Rephrase</span>" + icon("meta"), "rephrase", "ai-action", 'aria-label="Rephrase with Meta"')}${button(icon("stars-linear") + "<span>Create with Meta</span>" + icon("meta"), "ai-draft", "ai-action")}${button("Check question", "studio-review", "quiet small")}</div><p class="compose-format-label">${formats[e.type][0]}</p><div class="compose-options">${e.options.map((o, i) => `<div class="option-input"><input class="field editor-option" id="editor-option-${i}" data-index="${i}" aria-label="Option ${i + 1}" placeholder="Answer ${i + 1}" value="${esc(o)}" maxlength="100">${e.options.length > 2 && e.type !== "slider" ? ib("close-circle-linear", `Remove option ${i + 1}`, "remove-option", `data-index="${i}"`) : ""}</div>`).join("")}${!["ab", "slider"].includes(e.type) && e.options.length < 5 ? button("Add another option", "add-option", "add-option") : ""}</div>${["image", "ab"].includes(e.type) ? `<div class="upload-grid">${e.options.map((o, i) => `<div><label class="upload-box">${e.images[i] ? `<img src="${esc(e.images[i])}" alt="${esc(o)}">` : icon("gallery-linear")}<span>${e.images[i] ? "Replace" : "Upload"} image ${i + 1}</span><input type="file" accept="image/*" data-image="${i}" aria-label="Image ${i + 1}"></label>${button("Generate image", "generate-image", "quiet small", `data-index="${i}"`)}</div>`).join("")}</div>${e.imagePrompts?.length ? `<div class="studio-visual-plan"><p class="format-note">${e.imagePrompts.length} matching image briefs \xB7 existing images are kept.</p>${button("Generate missing visuals", "studio-images", "small")}</div>` : ""}${button("Review images with Meta", "analyse-images", "quiet small")}` : e.type === "audio" ? `<div class="action-row">${button(icon("microphone-3-linear") + " Voice studio", "voice-editor")}</div><label class="upload-box media-upload">${icon("headphones-round-linear")}<span id="media-filename">${esc(e.mediaName || "Choose audio (up to 60 seconds)")}</span><input type="file" accept="audio/*" id="editor-media" aria-label="Choose audio file"></label>${e.mediaURL ? `<audio controls src="${esc(e.mediaURL)}"></audio><span class="ai-label">${e.audio_origin === "generated" ? "AI voice" : "Human-created audio"}</span>${button("Transcribe with Meta", "transcribe-question", "quiet small")}` : ""}<label><span class="field-label">Transcript or description</span><textarea class="field" data-editor-field="transcript" maxlength="3000">${esc(e.transcript || "")}</textarea></label>` : e.type === "video" ? `<div class="video-options">${e.options.map((o, i) => `<label class="upload-box media-upload">${e.videos[i] ? `<video controls src="${esc(e.videos[i])}"></video>` : icon("videocamera-record-linear")}<span>${esc(o)} \xB7 MP4 or WebM, up to 60 seconds</span><input type="file" accept="video/mp4,video/webm" data-video="${i}" aria-label="Video for option ${i + 1}"></label>`).join("")}</div>` : ""}${c.connected.editorExtras()}<details class="audience-details" ${state.audienceOpen ? "open" : ""}><summary>Audience and budget ${icon("alt-arrow-down-linear", "sm")}</summary><div class="audience-body"><fieldset><legend>Topics \xB7 up to 5</legend><div class="topic-picks">${["Design", "Lifestyle", "Work", "Food", "Technology", "Travel", "Entertainment", "Wellbeing"].map((t) => `<button type="button" class="chip" data-action="editor-topic" data-topic="${t}" aria-pressed="${(e.tags || []).includes({ Design: "design", Lifestyle: "everyday", Work: "work", Food: "food", Technology: "technology", Travel: "travel", Entertainment: "entertainment", Wellbeing: "wellbeing" }[t])}">${t}</button>`).join("")}</div></fieldset>${selectControl({ id: "editor-distribution", label: "Distribution", value: e.reach, field: "reach", options: [{ value: "Community", label: "Community", description: "Use community-funded places" }, { value: "Boost", label: "Boost", description: "Reserve responses with credits" }] })}<div class="budget-inputs"><label><span class="field-label">Responses</span><input class="field" id="response-count" type="number" min="1" max="${e.reach === "Boost" ? 500 : 50}" value="${e.count}"></label><label><span class="field-label">Open for (hours)</span><input class="field" type="number" data-editor-field="hours" min="1" max="720" value="${e.hours || 168}"></label></div>${selectControl({ id: "editor-language", label: "Language", value: e.language, field: "language", options: ["English", "Hindi", "Tamil", "Spanish"] })}<div class="budget-summary" id="budget-summary">${budgetSummary()}</div><p class="prototype-note">Time and rewards are estimated from poll complexity.</p></div></details></div></div><footer class="compose-footer">${button("Preview", "preview-editor", "quiet")}${button("Review poll", "review-poll", "primary")}</footer></form></main>`;
}
export function threadSingle(title,body,c,action=''){return `<main class="thread-single" id="main">${threadColumnHead(title,action,c)}<section class="thread-panel">${body}</section></main>`;}
